/* Govstack local Alpine shim.
 *
 * The current public shell does not depend on Alpine behavior yet. This keeps
 * the template asset reference valid until the real bundle is introduced.
 */
(function (global) {
  if (global.Alpine) {
    return;
  }

  global.Alpine = {
    version: "0.0.0-govstack-shim",
    start: function () {},
    plugin: function () {},
    data: function () {},
    store: function () {},
    bind: function () {},
    magic: function () {},
    effect: function () {},
    nextTick: function (callback) {
      return Promise.resolve().then(callback);
    },
  };
})(window);
